[{"order":1,"type":"heading","text":"Mastering Unity Addressables and Asset Management"},{"order":2,"type":"paragraph","text":"The Unity Addressables system provides an efficient way to manage game assets by addressing them via string keys. It simplifies loading content asynchronously, managing memory, and downloading remote asset bundles for live-service games."},{"order":3,"type":"subheading","text":"1. Installation and Setup"},{"order":4,"type":"bullet_point","text":"Open the Unity Package Manager via Window > Package Manager."},{"order":5,"type":"bullet_point","text":"Select 'Unity Registry' from the packages dropdown."},{"order":6,"type":"bullet_point","text":"Locate 'Addressables' and click Install."},{"order":7,"type":"subheading","text":"2. Marking Assets as Addressable"},{"order":8,"type":"paragraph","text":"To make any asset addressable, select it in your Project window, and in the Inspector, check the 'Addressable' checkbox. You can customize its unique address key directly in the Inspector or through the Addressables Groups window (Window > Asset Management > Addressables > Groups)."},{"order":9,"type":"subheading","text":"3. Loading Assets via Code"},{"order":10,"type":"paragraph","text":"Below is a standard implementation for loading a GameObject asynchronously using Addressables."},{"order":11,"type":"code","text":"using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;

public class AddressableLoader : MonoBehaviour
{
    [SerializeField] private AssetReference myPrefabReference;

    void Start()
    {
        myPrefabReference.InstantiateAsync().Completed += OnPrefabLoaded;
    }

    private void OnPrefabLoaded(AsyncOperationHandle<GameObject> handle)
    {
        if (handle.Status == AsyncOperationStatus.Succeeded)
        {
            GameObject loadedObject = handle.Result;
            Debug.Log("Successfully loaded: " + loadedObject.name);
        }
        else
        {
            Debug.LogError("Failed to load Addressable asset.");
        }
    }
}"},{"order":12,"type":"subheading","text":"4. Memory Management and Unloading"},{"order":13,"type":"paragraph","text":"Unlike traditional Resources.Load, Addressable assets consume memory until explicitly released. If you instantiate objects using an AssetReference, you must release them when they are no longer needed to prevent memory leaks."},{"order":14,"type":"code","text":"public void CleanupAsset(GameObject obj)
{
    myPrefabReference.ReleaseInstance(obj);
}"},{"order":15,"type":"subheading","text":"Conclusion"},{"order":16,"type":"paragraph","text":"By implementing Unity Addressables, you reduce initial build sizes, optimize memory allocation, and streamline content delivery for patches and DLCs."}]
